(* [comment removed for export] *)
Definition offstat (a n : Z) : Prop := a + n <= 0x10000 \/ 0xb8000 <= a.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition CLOSE_REMOTE_STACK : Z := 64 + MTX_UNLOCK_STACK.

(* [comment removed for export] *)
Definition cr_W (lo : Z) (sp : word) (stb : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (stb + 104, stb + 144); (stb + 192, stb + 240); (stb + 248, stb + 252)]%Z.

(* [comment removed for export] *)
Definition st_closed (S : statev) : statev := mkST (st_hdr S) 0 (st_fb S) STREAM_EOF (st_nread S) (st_nread_bytes S).

Definition close_remote_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (stb ioc implb lo : Z) (S : statev) (ds : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (cr_W lo sp stb) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ StateBlock LB m' stb ioc implb (st_closed S) ds
    /\ CanaryReads m'.

Definition close_remote_stmt : Prop :=
  forall (bs stb ioc implb lo : Z) (LB : list block) (S : statev) (ds : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  ro_cells usegs m bs [C8 (wz (stb + 32))] -> bs mod 8 = 0 ->
  (* [comment removed for export] *)
  StateBlock LB m stb ioc implb S ds -> st_lk S = 0 ->
  (st_fb S <> FB_empty -> fb_end (st_fb S) <= stb \/ stb + SZ_SPCI_STATE <= fb_begin (st_fb S)) ->
  CanaryReads m ->
  stk usegs m lo (bv_unsigned sp) -> lo + CLOSE_REMOTE_STACK <= bv_unsigned sp -> hceil <= lo ->
  (bs + 8 <= lo \/ bv_unsigned sp <= bs) -> (bs + 8 <= stb \/ stb + SZ_SPCI_STATE <= bs) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (close_remote_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB stb ioc implb lo S ds m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz bs) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_STREAM_CLOSE_REMOTE) fc None m (seg_rom usegs)).
